-- slicer label vs dqd coverage
SELECT (SELECT COUNT(*) FROM fact_student_submission WHERE school_id=:cfp AND subject='HS Physics' AND points_possible>0), (SELECT COUNT(*) FROM dim_question_data q JOIN dim_item di ON di.item_id=q.item_id WHERE di.school_id=:cfp AND q.subject='HS Physics'), (SELECT COUNT(*) FROM dim_question_data q JOIN dim_item di ON di.item_id=q.item_id JOIN dim_subject ds ON ds.school_id=di.school_id AND ds.subject_id=di.subject_id WHERE ds.subject='HS Physics');
-- end-to-end replica of CubeRepository.get_ytd_longitudinal_cells for subject='HS Physics': qd_first CTE (filtered qd.subject='HS Physics') is EMPTY -> every fact attempt LEFT-JOINs to NULL canon_std -> COALESCE(ds.cpalms_standard, qf.canon_std, 'Other') = 'Other' for 100% of rows

WITH per_item AS (SELECT school_id,item_id,MAX(subject) aligned_subject,MAX(grade) aligned_grade FROM dim_question_data GROUP BY 1,2),
j AS (SELECT pi.school_id,pi.item_id,pi.aligned_subject,pi.aligned_grade,dsub.subject true_subject,dsub.grade true_grade FROM per_item pi JOIN dim_item di ON di.item_id=pi.item_id AND di.school_id=pi.school_id JOIN dim_subject dsub ON dsub.subject_id=di.subject_id AND dsub.school_id=pi.school_id)
SELECT s.school_name, COUNT(*) FILTER (WHERE aligned_subject IS DISTINCT FROM true_subject) subj_mm, COUNT(*) FILTER (WHERE aligned_grade IS DISTINCT FROM true_grade) grade_mm FROM j JOIN dim_school s ON s.school_id=j.school_id GROUP BY 1;

WITH cqs AS (SELECT DISTINCT school_id,item_id,question_id FROM cube_question_summary), dqd AS (SELECT DISTINCT school_id,item_id,question_id FROM dim_question_data)
SELECT s.school_name, COUNT(*) questions_missing_from_dqd, COUNT(DISTINCT c.item_id) items_touched FROM cqs c LEFT JOIN dqd d USING(school_id,item_id,question_id) JOIN dim_school s ON s.school_id=c.school_id WHERE d.question_id IS NULL GROUP BY 1;
-- items fully absent from dqd:
WITH ci AS (SELECT DISTINCT school_id,item_id FROM cube_question_summary), di2 AS (SELECT DISTINCT school_id,item_id FROM dim_question_data)
SELECT s.school_name, COUNT(*) items_absent FROM ci c LEFT JOIN di2 d USING(school_id,item_id) JOIN dim_school s ON s.school_id=c.school_id WHERE d.item_id IS NULL GROUP BY 1;
